            return "0";
        }
        String sign = "";
        if (n < 0) {
            sign = "-";
            n = -n;
        }
        StringBuilder digits = new StringBuilder();
        while (n > 0) {
            digits.insert(0, Character.toString((char) ('0' + n % 10)));
            n /= 10;
        }
        return sign + digits.toString();
